function MillstoneEyeReamerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneEyeReamerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneEyeReamerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneEyeReamerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneEyeReamerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneEyeReamerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneEyeReamerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneEyeReamerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneEyeReamerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneEyeReamerMaker.buildings==0 then return false,"Potrebna razširjevalna delavnica" end; if not MillstoneEyeReamerMaker.maker then return false,"Potreben razsirjevalec" end; return true end
function MillstoneEyeReamerMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneEyeReamerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneEyeReamerMaker.ironStock=MillstoneEyeReamerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneEyeReamerMaker.bronzeStock=MillstoneEyeReamerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneEyeReamerMaker.woodStock=MillstoneEyeReamerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneEyeReamerMaker.leatherStock=MillstoneEyeReamerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneEyeReamerMaker.silverStock=MillstoneEyeReamerMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneEyeReamerMaker.goldStock=MillstoneEyeReamerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneEyeReamerMaker.jewelStock=MillstoneEyeReamerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneEyeReamerMaker.pearlStock=MillstoneEyeReamerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneEyeReamerMaker.maker then t=math.max(1,t-math.floor(MillstoneEyeReamerMaker.maker.skill/13)) end; table.insert(MillstoneEyeReamerMaker.activeMaking,{id="millstoneeyereamer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneEyeReamerMaker.completeMaking(m) local q=1.0+(MillstoneEyeReamerMaker.getQualityBonus()/100); if MillstoneEyeReamerMaker.maker then q=q+(MillstoneEyeReamerMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneEyeReamerMaker.productStock[m.productType]=(MillstoneEyeReamerMaker.productStock[m.productType] or 0)+m.quantity; MillstoneEyeReamerMaker.totalProducts=MillstoneEyeReamerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneEyeReamerMaker.maker then MillstoneEyeReamerMaker.maker.itemsMade=MillstoneEyeReamerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneEyeReamerMaker.maker.skill=math.min(100,MillstoneEyeReamerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Razširjevalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstoneeyereamer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneEyeReamerMaker.update(dt) if not _G.state then return end; MillstoneEyeReamerMaker.dayTimer=MillstoneEyeReamerMaker.dayTimer+dt; if MillstoneEyeReamerMaker.dayTimer>=30 then MillstoneEyeReamerMaker.dayTimer=0; for i=#MillstoneEyeReamerMaker.activeMaking,1,-1 do local m=MillstoneEyeReamerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneEyeReamerMaker.completeMaking(m); table.remove(MillstoneEyeReamerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneEyeReamerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneEyeReamerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
